function validate([arr1, arr2]) {
  if (arr1.length < 1 || arr1.length > 2000) return 'arr1 needs 1 to 2000 values.';
  if (arr2.length < 1 || arr2.length > 2000) return 'arr2 needs 1 to 2000 values.';
  const ok = v => Number.isInteger(v) && v >= 0 && v <= 1000000000;
  if (!arr1.every(ok) || !arr2.every(ok)) return 'Every value is an integer from 0 to 10^9.';
  return null;
}

