function makeArrayIncreasing(arr1, arr2) {
  const sorted = [...new Set(arr2)].sort((a, b) => a - b);
  const n = arr1.length;
  const firstAbove = (value) => {
    let left = 0;
    let right = sorted.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (sorted[mid] <= value) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  };

  let dp = new Array(n + 1).fill(Infinity);
  dp[0] = -1;
  for (let i = 0; i < n; i++) {
    const next = new Array(n + 1).fill(Infinity);
    for (let j = 0; j <= i + 1; j++) {
      if (arr1[i] > dp[j]) {
        next[j] = arr1[i];
      }
      if (j > 0 && dp[j - 1] !== Infinity) {
        const k = firstAbove(dp[j - 1]);
        if (k < sorted.length) {
          next[j] = Math.min(next[j], sorted[k]);
        }
      }
    }
    dp = next;
  }

  for (let j = 0; j <= n; j++) {
    if (dp[j] !== Infinity) {
      return j;
    }
  }
  return -1;
}

