function makeArrayIncreasing(arr1, arr2) {
  // Try every choice at every index: keep arr1[i], or replace it with any value of arr2.
  const options = [...new Set(arr2)];
  let best = Infinity;
  const explore = (i, previous, used) => {
    if (used >= best) return;
    if (i === arr1.length) { best = used; return; }
    if (arr1[i] > previous) explore(i + 1, arr1[i], used);
    for (const value of options) if (value > previous) explore(i + 1, value, used + 1);
  };
  explore(0, -Infinity, 0);
  return best === Infinity ? -1 : best;
}

